'use strict';
const scope=document.createElement('div');scope.id='scope-summary';scope.className='scope-summary';scope.innerHTML='<div class="scope-header"><div><span class="scope-eyebrow">THE FIRST RELEASE / SCOPE AT A GLANCE</span><h3>A clear scope.<br><span>A few decisions together.</span></h3><p>Explore each building block to see what we propose—and what we need to agree.</p></div><span class="scope-label">Proposed MVP</span></div><div class="scope-cards"><details class="scope-card"><summary><span class="scope-card-icon" data-icon="globe"></span><span class="scope-card-copy"><strong>Public website</strong><span>Priority Astro pages with a clear path to membership and enquiries.</span><small>Explore the decision <span data-icon="arrow"></span></small></span><span class="scope-toggle" data-icon="plus"></span></summary><div class="scope-card-decision"><span class="scope-decision-label">TO AGREE TOGETHER</span><p>Agree priority templates and the content migration volume.</p></div></details><details class="scope-card"><summary><span class="scope-card-icon" data-icon="edit"></span><span class="scope-card-copy"><strong>Independent publishing</strong><span>Approved content blocks and preview, so editors can update safely.</span><small>Explore the decision <span data-icon="arrow"></span></small></span><span class="scope-toggle" data-icon="plus"></span></summary><div class="scope-card-decision"><span class="scope-decision-label">TO AGREE TOGETHER</span><p>Trial Storyblok with real editors; confirm CMS fit, roles and licensing.</p></div></details><details class="scope-card"><summary><span class="scope-card-icon" data-icon="lock"></span><span class="scope-card-copy"><strong>Owned member portal</strong><span>A branded home for agreed resources, with verified member access.</span><small>Explore the decision <span data-icon="arrow"></span></small></span><span class="scope-toggle" data-icon="plus"></span></summary><div class="scope-card-decision"><span class="scope-decision-label">TO AGREE TOGETHER</span><p>Confirm member roles, protected resources, ZoomForth parity and backend milestones.</p></div></details><details class="scope-card"><summary><span class="scope-card-icon" data-icon="layers"></span><span class="scope-card-copy"><strong>Connected research</strong><span>A first reusable microsite template and shared pathways.</span><small>Explore the decision <span data-icon="arrow"></span></small></span><span class="scope-toggle" data-icon="plus"></span></summary><div class="scope-card-decision"><span class="scope-decision-label">TO AGREE TOGETHER</span><p>Audit existing sites for reuse; agree the first template and domain strategy.</p></div></details><details class="scope-card"><summary><span class="scope-card-icon" data-icon="connect"></span><span class="scope-card-copy"><strong>HubSpot enquiries</strong><span>An agreed form journey with validation and clear submission states.</span><small>Explore the decision <span data-icon="arrow"></span></small></span><span class="scope-toggle" data-icon="plus"></span></summary><div class="scope-card-decision"><span class="scope-decision-label">TO AGREE TOGETHER</span><p>Confirm CRM access, consent, field mapping and backend integration ownership.</p></div></details><details class="scope-card"><summary><span class="scope-card-icon" data-icon="shield"></span><span class="scope-card-copy"><strong>A verified launch</strong><span>SEO, agreed migration checks, QA, training and handover.</span><small>Explore the decision <span data-icon="arrow"></span></small></span><span class="scope-toggle" data-icon="plus"></span></summary><div class="scope-card-decision"><span class="scope-decision-label">TO AGREE TOGETHER</span><p>Agree acceptance gates, backend capacity, monitoring and rollback ownership.</p></div></details></div><div class="scope-boundary"><span data-icon="people"></span><p>We agree the boundaries before committing. Backend effort and milestones need confirmation; rebuilding every existing microsite is not assumed.</p></div>';document.querySelector('.tech-dock').after(scope);decorate(scope);
const polishSetCapability=setCapability;
setCapability=function(key){polishSetCapability(key);if(key==='cms')mountLeaderExercise()};
function portrait(k){const colors={coral:['#e3ac96','#9a5347'],blue:['#a8c4d4','#446883'],mint:['#afd0c3','#477769']}[k];return '<svg class="leader-portrait" viewBox="0 0 160 180" role="img" aria-label="Illustrative leader portrait"><rect width="160" height="180" rx="12" fill="'+colors[0]+'"/><circle cx="80" cy="65" r="29" fill="#f4ded0"/><path d="M51 65c-7-35 63-42 59 1-12-5-24-21-28-19-5 12-16 15-31 18" fill="'+colors[1]+'"/><path d="M27 180v-20c0-70 106-70 106 0v20" fill="'+colors[1]+'"/></svg>'}
function mountLeaderExercise(){const block=document.createElement('div');block.id='leader-exercise';block.className='leader-exercise';block.innerHTML='<div class="exercise-heading"><div><span class="kicker">TRY MANNY’S EVERYDAY TASK</span><h3>Replace a featured leader.</h3><p>Edit the content. Watch the layout stay aligned.</p></div><span class="tag">APPROVED COMPONENT</span></div><div class="exercise-grid"><div class="exercise-fields"><label>Name<input id="leader-name" maxlength="65" value="Alex Morgan"></label><label>Role<input id="leader-role" maxlength="90" value="Business leader & inclusion advocate"></label><label>Description<textarea id="leader-description" maxlength="200">Connecting equality with stronger business outcomes.</textarea></label><fieldset><legend>Choose a sample portrait</legend><div class="portrait-options">'+['coral','blue','mint'].map((k,i)=>'<button data-portrait="'+k+'" aria-label="'+k+' sample portrait" aria-pressed="'+(i===0)+'">'+portrait(k)+'</button>').join('')+'</div></fieldset><button class="button" id="leader-example">Try a replacement '+icon('arrow')+'</button></div><div class="leader-live"><span class="kicker">LIVE PREVIEW / SAMPLE CONTENT</span><div class="leader-card"><div id="leader-image">'+portrait('coral')+'</div><div><span class="leader-category">FEATURED LEADER</span><h4 id="leader-display-name">Alex Morgan</h4><strong id="leader-display-role">Business leader &amp; inclusion advocate</strong><p id="leader-display-description">Connecting equality with stronger business outcomes.</p></div></div><div class="layout-proof">'+icon('shield')+'<span>Spacing, image shape and responsive layout belong to the component.</span></div><p id="leader-feedback" role="status">Start by changing the name or choosing a portrait.</p></div></div><small>Illustrative people and portraits. This demonstrates the proposed editing model, not the actual CMS interface. Edits stay in this page.</small></div>';document.querySelector('#builder').before(block);let image='coral';function update(){['name','role','description'].forEach(k=>document.querySelector('#leader-display-'+k).textContent=document.querySelector('#leader-'+k).value);document.querySelector('#leader-image').innerHTML=portrait(image);document.querySelector('#leader-feedback').textContent='Content updated. The approved layout stays aligned.'}['name','role','description'].forEach(k=>document.querySelector('#leader-'+k).addEventListener('input',update));document.querySelectorAll('[data-portrait]').forEach(b=>b.onclick=()=>{image=b.dataset.portrait;document.querySelectorAll('[data-portrait]').forEach(n=>n.setAttribute('aria-pressed',n===b));update()});document.querySelector('#leader-example').onclick=()=>{document.querySelector('#leader-name').value='Jordan Lee';document.querySelector('#leader-role').value='Global leadership & talent strategy';document.querySelector('#leader-description').value='Building inclusive teams that help businesses grow.';document.querySelector('[data-portrait="blue"]').click()}}
const checkpoints=['Blueprint agreed','Publishing pilot','Member & campaign review','MVP candidate','QA reviewed','Launch gate'];const mobilePlan=document.createElement('div');mobilePlan.className='mobile-plan';mobilePlan.innerHTML='<p class="mobile-plan-hint">Six phases. Select a week to see its output below.</p>'+stages.map((s,i)=>'<article class="mobile-phase"><div class="mobile-phase-heading">'+icon(s.icon)+'<div><small>WEEKS '+String(i*2+1).padStart(2,'0')+'–'+String(i*2+2).padStart(2,'0')+' · '+(i<4?'BUILD':'QA & LAUNCH')+'</small><h3>'+s.name+'</h3></div></div><p>'+s.summary+'</p><div class="mobile-week-buttons">'+[i*2,i*2+1].map(n=>'<button data-mobile-week="'+n+'" aria-pressed="false"><strong>Week '+(n+1)+'</strong><span>'+weeks[n].title+'</span></button>').join('')+'</div><div class="mobile-checkpoint">'+icon('check')+'<span>'+(i===2?'Review: ':'Checkpoint: ')+checkpoints[i]+'</span></div><div class="mobile-seo">'+icon('search')+' SEO: '+(i===0?'Structure & URL plan':i===1?'Metadata & crawlable links':i===2?'Private indexing & campaign tracking':i===3?'Redirects & migration checks':i===4?'Crawl & performance validation':'Production checks & monitoring')+'</div></article>').join('');document.querySelector('.plan-scroll').before(mobilePlan);document.querySelectorAll('[data-mobile-week]').forEach(b=>b.onclick=()=>{pickWeek(Number(b.dataset.mobileWeek));document.querySelector('.stage-panel').scrollIntoView({block:'start',behavior:'smooth'})});function syncMobile(i){document.querySelectorAll('[data-mobile-week]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.mobileWeek)===i))}document.addEventListener('proposal-week',e=>syncMobile(e.detail));syncMobile(selectedWeek);
const decision=document.querySelector('.footer-checkpoints');decision.className='approval-checklist';decision.innerHTML='<div class="approval-items">'+[['First-release scope','Priority templates, member use cases, first microsite and enquiry flow.'],['Editor trial','Test the candidate CMS with your real content and team.'],['Migration boundaries','Agree what moves, what stays and how links and access are preserved.'],['Backend coordination','Confirm APIs, owners, capacity and delivery milestones.']].map(([t,d],i)=>'<label><input type="checkbox" data-decision="'+i+'"><span><strong>'+t+'</strong><small>'+d+'</small></span></label>').join('')+'</div><p id="decision-progress" role="status">0 of 4 discussion points marked as reviewed.</p><small>Local discussion aid only. Checking a box does not approve scope or send anything.</small>';document.querySelectorAll('[data-decision]').forEach(b=>b.onchange=()=>{const n=document.querySelectorAll('[data-decision]:checked').length;document.querySelector('#decision-progress').textContent=n+' of 4 discussion points marked as reviewed.'+(n===4?' Ready for a scope discussion.':'')});
const walk=document.createElement('div');walk.id='walk-bar';walk.className='walk-bar';walk.hidden=true;walk.innerHTML='<div><small id="walk-count"></small><strong id="walk-title"></strong><span id="walk-instruction"></span></div><div><button id="walk-back" aria-label="Previous walkthrough step">'+icon('left')+'</button><button id="walk-next">Next '+icon('arrow')+'</button><button id="walk-close" aria-label="Close walkthrough">'+icon('plus')+'</button></div>';document.body.append(walk);let walkthrough=0;const walkSteps=[['Edit without breaking the design','Replace the sample leader or edit a field.','#leader-exercise'],['Understand member access','Switch Visitor / Member, then check resource access.','#platform-panel'],['See the delivery plan','Select a phase or week. Explore its deliverables.','#roadmap']];function showWalk(i){walkthrough=i;walk.hidden=false;const s=walkSteps[i];if(i===0)setCapability('cms');if(i===1)setCapability('portal');document.querySelector('#walk-count').textContent='GUIDED WALKTHROUGH · '+(i+1)+' / 3';document.querySelector('#walk-title').textContent=s[0];document.querySelector('#walk-instruction').textContent=s[1];document.querySelector('#walk-back').disabled=i===0;document.querySelector('#walk-next').innerHTML=(i===2?'Review the decisions':'Next')+icon('arrow');requestAnimationFrame(()=>document.querySelector(s[2]).scrollIntoView({block:'start',behavior:'smooth'}))}document.querySelector('#walk-start').onclick=()=>showWalk(0);document.querySelector('#walk-next').onclick=()=>{if(walkthrough<2)showWalk(walkthrough+1);else{walk.hidden=true;document.querySelector('#decision').scrollIntoView({block:'start',behavior:'smooth'})}};document.querySelector('#walk-back').onclick=()=>showWalk(Math.max(0,walkthrough-1));document.querySelector('#walk-close').onclick=()=>{walk.hidden=true;document.querySelector('#walk-start').focus({preventScroll:true})};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!walk.hidden)document.querySelector('#walk-close').click()});
